import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { Link, useNavigate } from '@tanstack/react-router';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Activity, ArrowDownLeft, ArrowDownRight, ArrowLeftRight, ArrowRight, ArrowUpRight, BadgeCheck, Bell, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardList, Copy, Download, FileBarChart, FileClock, Landmark, LayoutDashboard, LockKeyhole, LogOut, Menu, Moon, MoreHorizontal, PauseCircle, Plus, RefreshCw, Search, Shield, ShieldCheck, Sun, Users, Wallet, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { api, clearSession, errorMessage, formatMoney, formatPrice, mapWsEvent, PRICE_SCALE, purgeLegacySession, shortAddress, TOKEN_KEY, USER_KEY, WS_URL } from '@/lib/api';
import type { AuditEvent, CustodyAction, DemoUser, Investor, Order, Role, TxResult } from '@/lib/types';

type Page = 'dashboard' | 'investors' | 'orders' | 'nav' | 'transfers' | 'custody' | 'admin' | 'reports' | 'audit' | 'live';
const nav: { id: Page; label: string; icon: typeof LayoutDashboard; group: string }[] = [
  { id: 'dashboard', label: 'Overview', icon: LayoutDashboard, group: 'WORKSPACE' },
  { id: 'investors', label: 'Investors', icon: Users, group: 'WORKSPACE' },
  { id: 'orders', label: 'Orders', icon: ArrowLeftRight, group: 'WORKSPACE' },
  { id: 'nav', label: 'NAV management', icon: Activity, group: 'WORKSPACE' },
  { id: 'transfers', label: 'Transfers', icon: ArrowUpRight, group: 'WORKSPACE' },
  { id: 'custody', label: 'Custody', icon: LockKeyhole, group: 'OPERATIONS' },
  { id: 'reports', label: 'Reports', icon: FileBarChart, group: 'OPERATIONS' },
  { id: 'audit', label: 'Audit trail', icon: FileClock, group: 'OPERATIONS' },
  { id: 'live', label: 'Live feed', icon: Activity, group: 'OPERATIONS' },
  { id: 'admin', label: 'Administration', icon: Shield, group: 'OPERATIONS' },
];
const titles: Record<Page, { title: string; subtitle: string }> = {
  dashboard: { title: 'Fund overview', subtitle: 'A complete picture of your fund, in real time.' }, investors: { title: 'Investors', subtitle: 'Manage your investor registry and compliance status.' }, orders: { title: 'Orders', subtitle: 'Track subscriptions and redemptions through settlement.' }, nav: { title: 'NAV management', subtitle: 'Review valuation history and publish the latest NAV.' }, transfers: { title: 'Transfers', subtitle: 'Move fund units securely between approved investors.' }, custody: { title: 'Custody', subtitle: 'Monitor positions and manage custody instructions.' }, admin: { title: 'Administration', subtitle: 'Control fund operations and review role assignments.' }, reports: { title: 'Reports', subtitle: 'Generate investor statements and review transactions.' }, audit: { title: 'Audit trail', subtitle: 'Trace every operation back to its on-chain record.' }, live: { title: 'Live feed', subtitle: 'A real-time view of fund activity.' },
};
const date = (s: string) => new Date(s).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const datetime = (s: string) => `${date(s)} · ${new Date(s).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' })} UTC`;
const num = (n: number) => new Intl.NumberFormat('en-US').format(n);
const investorRole = (r?: Role) => Boolean(r?.startsWith('investor'));
const can = (user: DemoUser | null, action: 'agent' | 'admin' | 'custodian' | 'investor') => user?.username === action || (action === 'investor' && investorRole(user?.username));
function useData<T>(key: string, fn: () => Promise<T>) { return useQuery({ queryKey: [key], queryFn: fn, refetchInterval: 30000 }); }
function useAct() { const qc = useQueryClient(); return async <T,>(fn: () => Promise<T>, success: string): Promise<T | undefined> => { try { const result = await fn(); toast.success(success); await qc.invalidateQueries(); return result; } catch (e) { toast.error(errorMessage(e)); return undefined; } }; }
function AddressChip({ value }: { value: string }) { return <span className="inline-flex items-center gap-1.5 font-mono text-xs text-muted-foreground"><span>{shortAddress(value)}</span><Button variant="ghost" size="icon" className="size-5" title="Copy address" onClick={() => { void navigator.clipboard.writeText(value); toast.success('Address copied'); }}><Copy className="size-3!" /></Button></span>; }
function TxHashChip({ value, block }: { value?: string | undefined; block?: number | undefined }) { if (!value) return <span className="text-muted-foreground">—</span>; return <span className="inline-flex items-center gap-1 font-mono text-xs text-primary"><span>{shortAddress(value)}</span><Button variant="ghost" size="icon" className="size-5" title="Copy transaction hash" onClick={() => { void navigator.clipboard.writeText(value); toast.success('Transaction hash copied'); }}><Copy className="size-3!" /></Button>{block != null && <span className="text-muted-foreground">#{block}</span>}</span>; }
function StatusBadge({ value }: { value: string }) { const tone = ['SETTLED', 'APPROVED', 'MATCH', 'ACTIVE'].includes(value) ? 'bg-positive-soft text-positive' : ['PENDING', 'LOCK'].includes(value) ? 'bg-warning-soft text-warning' : ['CANCELLED','REJECTED','REVOKED','FROZEN','MISMATCH','PAUSED'].includes(value) ? 'bg-danger-soft text-destructive' : 'bg-muted text-muted-foreground'; return <span className={`inline-flex items-center gap-1.5 rounded px-2 py-1 text-[10px] font-bold tracking-wide ${tone}`}><span className="size-1.5 rounded-full bg-current" />{value}</span>; }
function SectionHead({ title, aside }: { title: string; aside?: ReactNode }) { return <div className="mb-5 flex items-center justify-between gap-3"><h2 className="font-display text-base font-bold text-foreground">{title}</h2>{aside}</div>; }
function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={`rounded-md border border-border bg-card ${className}`}>{children}</div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block space-y-2 text-xs font-semibold text-foreground"><span>{label}</span>{children}</label>; }
function SelectField({ value, onChange, children }: { value: string; onChange: (s: string) => void; children: ReactNode }) { return <select className="h-9 w-full rounded-md border border-input bg-background px-3 text-sm text-foreground outline-none focus:border-primary" value={value} onChange={e => onChange(e.target.value)}>{children}</select>; }
function Empty({ text = 'No records found' }: { text?: string }) { return <div className="p-12 text-center text-sm text-muted-foreground">{text}</div>; }
function DataTable<T>({ rows, columns, pageSize = 7 }: { rows: T[]; columns: { title: string; render: (item: T) => ReactNode; className?: string }[]; pageSize?: number }) {
  const [page, setPage] = useState(1); const max = Math.max(1, Math.ceil(rows.length / pageSize)); const actual = Math.min(page, max);
  return <><div className="overflow-x-auto"><table className="w-full min-w-170 text-left"><thead className="border-y border-border bg-muted/50"><tr>{columns.map((c, i) => <th key={i} className={`px-5 py-3 text-[10px] font-bold uppercase tracking-widest text-muted-foreground ${c.className || ''}`}>{c.title}</th>)}</tr></thead><tbody className="divide-y divide-border">{rows.slice((actual - 1) * pageSize, actual * pageSize).map((row, i) => <tr key={i} className="transition-colors hover:bg-muted/40">{columns.map((c, j) => <td key={j} className={`px-5 py-4 text-sm ${c.className || ''}`}>{c.render(row)}</td>)}</tr>)}</tbody></table>{!rows.length && <Empty />}</div><div className="flex items-center justify-between border-t border-border px-5 py-3 text-xs text-muted-foreground"><span>Showing {rows.length ? (actual - 1) * pageSize + 1 : 0}–{Math.min(actual * pageSize, rows.length)} of {rows.length}</span><div className="flex items-center gap-1"><Button variant="ghost" size="icon" className="size-7" disabled={actual === 1} onClick={() => setPage(actual - 1)} aria-label="Previous page"><ChevronLeft /></Button><span className="px-2">{actual} / {max}</span><Button variant="ghost" size="icon" className="size-7" disabled={actual === max} onClick={() => setPage(actual + 1)} aria-label="Next page"><ChevronRight /></Button></div></div></>;
}
function Receipt({ receipt }: { receipt: TxResult | null }) { if (!receipt) return null; return <div className="rounded-md border border-positive/30 bg-positive-soft p-3 text-sm"><div className="mb-2 flex items-center gap-2 font-semibold text-positive"><BadgeCheck className="size-4" />{receipt.message}</div><TxHashChip value={receipt.txHash} block={receipt.blockNumber} /></div>; }
function ConfirmDialog({ open, setOpen, title, description, confirm, destructive, onConfirm }: { open: boolean; setOpen: (b: boolean) => void; title: string; description: string; confirm: string; destructive?: boolean; onConfirm: () => void }) { return <AlertDialog open={open} onOpenChange={setOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{title}</AlertDialogTitle><AlertDialogDescription>{description}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancel</AlertDialogCancel><AlertDialogAction className={destructive ? 'bg-destructive text-destructive-foreground hover:bg-destructive/90' : ''} onClick={onConfirm}>{confirm}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>; }
function Metric({ label, value, note, icon: Icon, positive }: { label: string; value: string; note: string; icon: typeof Activity; positive?: boolean }) { return <Panel className="min-w-0 p-5"><div className="flex items-start justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span><div className="flex size-8 items-center justify-center rounded bg-secondary text-primary"><Icon className="size-4" /></div></div><div className="mt-4 truncate font-display text-[25px] font-bold tracking-tight">{value}</div><div className={`mt-1 text-xs ${positive ? 'text-positive' : 'text-muted-foreground'}`}>{note}</div></Panel>; }
function Login({ onLogin }: { onLogin: (s: { access_token: string; user: DemoUser }) => void }) { const { data: users = [] } = useData('demo-users', api.getDemoUsers); const [username, setUsername] = useState('agent'); const [password, setPassword] = useState('demo'); const [busy, setBusy] = useState(false); const login = async (e: React.FormEvent) => { e.preventDefault(); setBusy(true); try { const session = await api.login(username, password); onLogin(session); toast.success(`Welcome back, ${session.user.name}`); } catch (e) { toast.error(errorMessage(e)); } finally { setBusy(false); } }; return <div className="flex min-h-screen flex-col bg-background lg:flex-row"><div className="flex flex-col justify-between bg-sidebar px-8 py-9 text-sidebar-foreground lg:w-1/2 lg:px-16 lg:py-14"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-md bg-primary text-primary-foreground"><Landmark className="size-5" /></div><span className="font-display text-xl font-extrabold">aperture<span className="text-primary">.</span></span></div><div className="max-w-xl py-20 lg:py-0"><span className="mb-6 inline-block border-l-2 border-primary pl-3 text-xs font-bold uppercase tracking-widest text-sidebar-muted">FUND OPERATIONS · REIMAGINED</span><h1 className="font-display text-4xl font-bold leading-tight lg:text-6xl">Clarity for every<br /><span className="text-primary">fund operation.</span></h1><p className="mt-6 max-w-md text-base leading-7 text-sidebar-muted">One secure workspace for digital asset servicing, investor operations, and on-chain transparency.</p></div><p className="text-xs text-sidebar-muted">© 2026 Aperture Fund Services · Institutional platform</p></div><div className="flex flex-1 items-center justify-center px-6 py-12"><div className="w-full max-w-97.5"><div className="mb-9"><div className="mb-3 text-xs font-bold uppercase tracking-widest text-primary">SECURE ACCESS</div><h2 className="font-display text-3xl font-bold">Sign in to your workspace</h2><p className="mt-2 text-sm text-muted-foreground">Select a demo account to explore the console.</p></div><form onSubmit={login} className="space-y-5"><Field label="Account"><SelectField value={username} onChange={setUsername}>{users.map(u => <option key={u.username} value={u.username}>{u.name} · {u.username}</option>)}</SelectField></Field><Field label="Password"><Input type="password" value={password} onChange={e => setPassword(e.target.value)} required /></Field><Button className="h-11 w-full" disabled={busy}>{busy ? 'Signing in…' : 'Sign in'}<ArrowRight className="size-4" /></Button></form><div className="mt-6 rounded-md border border-border bg-card p-4 text-xs leading-5 text-muted-foreground"><span className="font-semibold text-foreground">Demo access</span><br />Password for every account: <span className="font-mono text-foreground">demo</span></div></div></div></div>; }
export function FundConsole({ page }: { page: Page }) {
  const [user, setUser] = useState<DemoUser | null>(null); const [ready, setReady] = useState(false); const [mobileMenu, setMobileMenu] = useState(false); const [dark, setDark] = useState(false); const qc = useQueryClient(); const navigate = useNavigate();
  useEffect(() => { purgeLegacySession(); const saved = window.localStorage.getItem(USER_KEY); const token = window.localStorage.getItem(TOKEN_KEY); if (saved && token) { try { setUser(JSON.parse(saved)); } catch { clearSession(); } } else { clearSession(); } setReady(true); setDark(document.documentElement.classList.contains('dark')); const unauthorized = () => { setUser(null); void navigate({ to: '/' }); toast.error('Session expired. Please sign in again.'); }; window.addEventListener('fund:unauthorized', unauthorized); return () => window.removeEventListener('fund:unauthorized', unauthorized); }, [navigate]);
  const signIn = (session: { access_token: string; user: DemoUser }) => { window.localStorage.setItem(TOKEN_KEY, session.access_token); window.localStorage.setItem(USER_KEY, JSON.stringify(session.user)); setUser(session.user); void qc.invalidateQueries(); };
  const signOut = () => { clearSession(); setUser(null); void navigate({ to: '/' }); };
  const toggleDark = () => { document.documentElement.classList.toggle('dark'); setDark(v => !v); };
  if (!ready) return <div className="min-h-screen bg-background" />;
  if (!user) return <Login onLogin={signIn} />;
  return <div className="min-h-screen bg-background"><div className="flex min-h-screen"><aside className={`fixed inset-y-0 left-0 z-40 flex w-62 flex-col bg-sidebar text-sidebar-foreground transition-transform lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${mobileMenu ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-19 items-center justify-between border-b border-sidebar-foreground/10 px-6"><Link to="/" onClick={() => setMobileMenu(false)} className="flex items-center gap-2.5"><div className="flex size-8 items-center justify-center rounded bg-primary text-primary-foreground"><Landmark className="size-4" /></div><span className="font-display text-[20px] font-extrabold">aperture<span className="text-primary">.</span></span></Link><Button variant="ghost" size="icon" className="text-sidebar-foreground lg:hidden" onClick={() => setMobileMenu(false)} aria-label="Close menu"><X /></Button></div><div className="px-4 pt-6"><div className="rounded border border-sidebar-foreground/10 bg-sidebar-foreground/5 p-3"><div className="text-[10px] font-bold uppercase tracking-widest text-sidebar-muted">ACTIVE FUND</div><div className="mt-2 flex items-center justify-between gap-2"><span className="truncate text-xs font-bold">Aperture Digital Credit</span><ChevronDown className="size-3 text-sidebar-muted" /></div><div className="mt-1 text-[11px] text-sidebar-muted">ADCF · Tokenised fund</div></div></div><nav className="flex-1 overflow-y-auto px-3 py-5">{['WORKSPACE','OPERATIONS'].map(group => <div key={group} className="mb-6"><div className="px-3 pb-2 text-[10px] font-bold tracking-[.14em] text-sidebar-muted">{group}</div>{nav.filter(n => n.group === group).map(item => <Link key={item.id} to={item.id === 'dashboard' ? '/' : `/${item.id}` as '/investors'} onClick={() => setMobileMenu(false)} className={`mb-0.5 flex h-10 items-center gap-3 rounded px-3 text-[13px] font-medium transition-colors ${page === item.id ? 'bg-primary/20 text-sidebar-foreground' : 'text-sidebar-muted hover:bg-sidebar-foreground/10 hover:text-sidebar-foreground'}`}><item.icon className={`size-4 ${page === item.id ? 'text-primary' : ''}`} />{item.label}{page === item.id && <span className="ml-auto size-1.5 rounded-full bg-primary" />}</Link>)}</div>)}</nav><div className="border-t border-sidebar-foreground/10 p-4"><div className="flex items-center gap-3 rounded p-2"><div className="flex size-9 shrink-0 items-center justify-center rounded bg-primary/25 text-xs font-bold text-primary">{user.name.split(' ').map(x => x[0]).slice(0,2).join('')}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{user.name}</div><div className="text-[11px] capitalize text-sidebar-muted">{user.username}</div></div><Button variant="ghost" size="icon" className="size-7 text-sidebar-muted hover:text-sidebar-foreground" onClick={signOut} title="Sign out"><LogOut className="size-4" /></Button></div></div></aside>{mobileMenu && <div className="fixed inset-0 z-30 bg-foreground/50 lg:hidden" onClick={() => setMobileMenu(false)} />}<div className="flex min-w-0 flex-1 flex-col"><header className="flex h-19 items-center justify-between gap-4 border-b border-border bg-card px-5 lg:px-9"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMobileMenu(true)} aria-label="Open menu"><Menu /></Button><span className="hidden text-xs text-muted-foreground sm:block">Workspace</span><ChevronRight className="hidden size-3 text-muted-foreground sm:block" /><span className="text-sm font-semibold">{titles[page].title}</span></div><div className="flex items-center gap-2 sm:gap-4"><div className="hidden items-center gap-2 rounded border border-positive/20 bg-positive-soft px-2.5 py-1.5 text-[11px] font-bold text-positive md:flex"><span className="live-dot size-1.5 rounded-full bg-positive" />LIVE ENVIRONMENT</div><Button variant="ghost" size="icon" onClick={toggleDark} title={dark ? 'Switch to light mode' : 'Switch to dark mode'}>{dark ? <Sun /> : <Moon />}</Button><div className="hidden h-7 w-px bg-border sm:block" /><div className="hidden text-right sm:block"><div className="text-xs font-bold">{user.name}</div><div className="font-mono text-[10px] text-muted-foreground">{shortAddress(user.address)}</div></div><div className="flex size-8 items-center justify-center rounded bg-secondary text-xs font-bold text-primary">{user.name.split(' ').map(x => x[0]).slice(0,2).join('')}</div></div></header><main className="w-full max-w-382.5 flex-1 px-5 pb-12 pt-8 lg:px-9 lg:pt-9"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><div className="mb-2 flex items-center gap-2 text-[11px] font-semibold text-muted-foreground"><span>APERTURE DIGITAL CREDIT FUND</span><span>·</span><span>{new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' })}</span></div><h1 className="font-display text-[28px] font-extrabold leading-tight lg:text-[32px]">{titles[page].title}</h1><p className="mt-1.5 text-sm text-muted-foreground">{titles[page].subtitle}</p></div><div className="flex items-center gap-2"><span className="rounded border border-border bg-card px-2.5 py-1.5 text-[11px] font-bold uppercase text-muted-foreground">{user.username}</span><Button variant="outline" size="sm" title="Refresh data" onClick={() => void qc.invalidateQueries()}><RefreshCw className="size-3.5" /><span className="hidden sm:inline">Refresh</span></Button></div></div><PageContent page={page} user={user} /></main><footer className="flex flex-wrap items-center justify-between gap-2 border-t border-border px-5 py-4 text-[11px] text-muted-foreground lg:px-9"><span>© 2026 Aperture Fund Services</span><span>Secure fund infrastructure · All times UTC</span></footer></div></div></div>;
}
function PageContent({ page, user }: { page: Page; user: DemoUser }) { switch(page) { case 'dashboard': return <Dashboard user={user} />; case 'investors': return <Investors user={user} />; case 'orders': return <Orders user={user} />; case 'nav': return <Nav user={user} />; case 'transfers': return <Transfers user={user} />; case 'custody': return <Custody user={user} />; case 'admin': return <Admin user={user} />; case 'reports': return <Reports user={user} />; case 'audit': return <Audit />; case 'live': return <Live />; } }
function PausedBanner() { const { data } = useData('fund-status', api.getFundStatus); return data?.paused ? <div className="mb-6 flex items-center gap-3 rounded border border-destructive/25 bg-danger-soft px-4 py-3 text-sm font-semibold text-destructive"><PauseCircle className="size-5" />Fund operations are paused. New orders are temporarily unavailable.</div> : null; }
function Dashboard({ user }: { user: DemoUser }) { const { data: status } = useData('fund-status', api.getFundStatus); const { data: summary } = useData('fund-summary', api.getFundSummary); const { data: performance = [] } = useData('nav-performance', api.getNavPerformance); const { data: orders = [] } = useData('orders', api.getOrders); const { data: events = [] } = useData('events', api.getAuditEvents); const chart = performance.map(p => ({ date: new Date(p.date).toLocaleDateString('en-GB', { month: 'short', day: 'numeric' }), value: p.nav / PRICE_SCALE / 1000000 })); return <><PausedBanner /><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Total net asset value" value={status ? formatMoney(status.nav) : '—'} note={`As of ${status?.asOf ? date(status.asOf) : '—'}`} icon={Landmark} /><Metric label="Unit price" value={status ? formatMoney(status.unitPrice) : '—'} note="Per tokenised fund unit" icon={Activity} /><Metric label="Active investors" value={String(status?.investors ?? '—')} note="Verified fund participants" icon={Users} /><Metric label="AUM performance" value={summary ? `+${summary.aumChange}%` : '—'} note="↑ Since fund inception" icon={ArrowUpRight} positive /></div><div className="grid gap-6 xl:grid-cols-[minmax(0,1.75fr)_minmax(300px,1fr)]"><Panel className="p-5 sm:p-6"><SectionHead title="NAV performance" aside={<span className="text-[11px] text-muted-foreground">Last 6 months</span>} /><div className="mb-5 flex items-baseline gap-3"><span className="font-display text-[27px] font-bold">{status ? formatMoney(status.nav) : '—'}</span><span className="rounded bg-positive-soft px-2 py-1 text-xs font-bold text-positive">+8.7%</span></div><div className="h-62.5 w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{ top: 4, right: 4, left: -28, bottom: 0 }}><defs><linearGradient id="nav-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--chart-line)" stopOpacity={.2} /><stop offset="100%" stopColor="var(--chart-line)" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="var(--border)" strokeDasharray="3 4" vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 10 }} interval="preserveStartEnd" /><YAxis tickLine={false} axisLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 10 }} domain={['dataMin - 0.3', 'dataMax + 0.3']} tickFormatter={(v: number) => `$${v.toFixed(1)}m`} /><Tooltip formatter={(v) => [`$${Number(v).toFixed(2)}m`, 'NAV']} contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 5, color: 'var(--foreground)', fontSize: 12 }} /><Area type="monotone" dataKey="value" stroke="var(--chart-line)" strokeWidth={2.5} fill="url(#nav-fill)" /></AreaChart></ResponsiveContainer></div></Panel><Panel className="p-5 sm:p-6"><SectionHead title="Fund at a glance" /><div className="divide-y divide-border">{[['Fund status', <StatusBadge value={status?.paused ? 'PAUSED' : 'ACTIVE'} />], ['Outstanding orders', <span className="font-bold">{summary?.pendingOrders ?? '—'}</span>], ['Settled orders', <span className="font-bold">{summary?.settledOrders ?? '—'}</span>], ['Total units issued', <span className="font-bold">{num(status?.totalUnits || 0)}</span>], ['Subscriptions', <span className="font-bold">{summary ? formatMoney(summary.subscriptions) : '—'}</span>], ['Redemptions', <span className="font-bold">{summary ? formatMoney(summary.redemptions) : '—'}</span>]].map(([label, value], i) => <div key={i} className="flex items-center justify-between gap-2 py-3.5 text-xs"><span className="text-muted-foreground">{label}</span>{value}</div>)}</div><Link to="/reports" className="mt-4 flex items-center justify-between border-t border-border pt-4 text-xs font-bold text-primary">Explore all reports <ArrowRight className="size-4" /></Link></Panel></div><div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1.75fr)_minmax(300px,1fr)]"><Panel><div className="p-5"><SectionHead title="Recent orders" aside={<Link to="/orders" className="flex items-center gap-1 text-xs font-bold text-primary">View all <ArrowRight className="size-3.5" /></Link>} /></div><DataTable rows={orders.slice(0,4)} columns={[{ title: 'Order', render: o => <span className="font-mono text-xs font-semibold">{o.id}</span> }, { title: 'Type', render: o => <span className="flex items-center gap-1.5 text-xs font-semibold">{o.type === 'SUBSCRIBE' ? <ArrowDownLeft className="size-3.5 text-positive" /> : <ArrowUpRight className="size-3.5 text-warning" />}{o.type}</span> }, { title: 'Value', render: o => <span className="font-semibold">{formatMoney(o.amount)}</span> }, { title: 'Status', render: o => <StatusBadge value={o.status} /> }]} /></Panel><Panel className="p-5 sm:p-6"><SectionHead title="Activity feed" aside={<span className="flex items-center gap-1.5 text-[10px] font-bold text-positive"><span className="live-dot size-1.5 rounded-full bg-positive" /> LIVE</span>} /><div className="space-y-0">{events.slice(0,4).map((e, i) => <div key={e.id} className="relative flex gap-3 pb-5 last:pb-0"><div className="flex flex-col items-center"><div className="z-10 mt-1 flex size-7 shrink-0 items-center justify-center rounded bg-secondary text-primary"><Activity className="size-3.5" /></div>{i < 3 && <div className="absolute top-8 bottom-0 w-px bg-border" />}</div><div><div className="text-xs font-semibold">{e.action}</div><div className="mt-1 text-[11px] text-muted-foreground">{e.actor} · {datetime(e.date)}</div></div></div>)}</div><Link to="/live" className="mt-5 flex items-center gap-1 text-xs font-bold text-primary">View live feed <ArrowRight className="size-3.5" /></Link></Panel></div></>; }
function Investors({ user }: { user: DemoUser }) { const { data: investors = [] } = useData('investors', api.getInvestors); const act = useAct(); const [search, setSearch] = useState(''); const [selected, setSelected] = useState<Investor | null>(null); const [newOpen, setNewOpen] = useState(false); const [form, setForm] = useState({ name: '', email: '', address: '' }); const [receipt, setReceipt] = useState<TxResult | null>(null); const filtered = investors.filter(i => `${i.name} ${i.address} ${i.email}`.toLowerCase().includes(search.toLowerCase())); const run = async (fn: () => Promise<TxResult>, label: string) => { const r = await act(fn, label); if (r) setReceipt(r); }; return <><PausedBanner /><Panel><div className="flex flex-wrap items-center justify-between gap-3 p-5"><div><h2 className="font-display text-base font-bold">Investor registry</h2><p className="mt-1 text-xs text-muted-foreground">{investors.length} registered investors</p></div><div className="flex flex-wrap gap-2"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input className="w-52 pl-9" placeholder="Search investors" value={search} onChange={e => setSearch(e.target.value)} /></div>{can(user, 'agent') && <Button size="sm" onClick={() => setNewOpen(true)}><Plus /> Register investor</Button>}</div></div><DataTable rows={filtered} columns={[{ title: 'Investor', render: i => <div><div className="font-semibold">{i.name}</div><div className="mt-1 text-xs text-muted-foreground">{i.email}</div></div> }, { title: 'Wallet address', render: i => <AddressChip value={i.address} /> }, { title: 'KYC', render: i => <StatusBadge value={i.kyc} /> }, { title: 'Units held', render: i => <span className="font-semibold">{num(i.units)}</span> }, { title: 'Joined', render: i => <span className="text-xs text-muted-foreground">{date(i.joined)}</span> }, { title: '', render: i => <Button variant="ghost" size="sm" onClick={() => { setSelected(i); setReceipt(null); }}>View <ArrowRight className="size-3" /></Button> }]} /></Panel><Dialog open={newOpen} onOpenChange={setNewOpen}><DialogContent><DialogHeader><DialogTitle>Register investor</DialogTitle><DialogDescription>Add a new address to the investor registry.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={async e => { e.preventDefault(); const result = await act(() => api.registerInvestor(form), 'Investor registered'); if (result) { setNewOpen(false); setForm({ name:'', email:'', address:'' }); } }}><Field label="Investor name"><Input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></Field><Field label="Email"><Input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></Field><Field label="Wallet address"><Input required placeholder="0x…" value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} /></Field><DialogFooter><Button type="submit">Register investor</Button></DialogFooter></form></DialogContent></Dialog><Dialog open={!!selected} onOpenChange={() => setSelected(null)}><DialogContent><DialogHeader><DialogTitle>{selected?.name}</DialogTitle><DialogDescription>Investor profile and compliance controls</DialogDescription></DialogHeader>{selected && <div className="space-y-5"><div className="grid grid-cols-2 gap-4 rounded bg-muted p-4 text-sm"><div><div className="mb-1 text-xs text-muted-foreground">KYC status</div><StatusBadge value={investors.find(i => i.address === selected.address)?.kyc || selected.kyc} /></div><div><div className="mb-1 text-xs text-muted-foreground">Fund units</div><b>{num(investors.find(i => i.address === selected.address)?.units || selected.units)}</b></div><div className="col-span-2"><div className="mb-1 text-xs text-muted-foreground">Address</div><AddressChip value={selected.address} /></div></div>{can(user, 'agent') && <div className="flex flex-wrap gap-2"><Button size="sm" onClick={() => void run(() => api.updateKyc(selected.address, 'approve'), 'KYC approved')}>Approve KYC</Button><Button size="sm" variant="outline" onClick={() => void run(() => api.updateKyc(selected.address, 'reject'), 'KYC rejected')}>Reject</Button><Button size="sm" variant="outline" onClick={() => void run(() => api.updateKyc(selected.address, 'revoke'), 'KYC revoked')}>Revoke</Button></div>}{can(user, 'admin') && <Button size="sm" variant="destructive" onClick={() => void run(() => api.setInvestorFreeze(selected.address, !(investors.find(i => i.address === selected.address)?.frozen)), 'Investor status updated')}>{investors.find(i => i.address === selected.address)?.frozen ? 'Unfreeze investor' : 'Freeze investor'}</Button>}<Receipt receipt={receipt} /></div>}</DialogContent></Dialog></>; }
function Orders({ user }: { user: DemoUser }) { const { data: all = [] } = useData('orders', api.getOrders); const { data: investors = [] } = useData('investors', api.getInvestors); const act = useAct(); const [filter, setFilter] = useState('ALL'); const [open, setOpen] = useState(false); const [type, setType] = useState<'subscribe'|'redeem'>('subscribe'); const [investor, setInvestor] = useState(user.address); const [units, setUnits] = useState(''); const [receipt, setReceipt] = useState<TxResult | null>(null); const [confirm, setConfirm] = useState<{ id: string; action: 'settle'|'cancel' } | null>(null); const visible = investorRole(user.username) ? all.filter(o => o.investor === user.address) : all; const filtered = filter === 'ALL' ? visible : visible.filter(o => o.status === filter); const investorName = (address: string) => investors.find(i => i.address === address)?.name || shortAddress(address); const perform = async () => { if (!confirm) return; const r = await act(() => confirm.action === 'settle' ? api.settleOrder(confirm.id) : api.cancelOrder(confirm.id), `Order ${confirm.action === 'settle' ? 'settled' : 'cancelled'}`); if (r) setReceipt(r); setConfirm(null); }; return <><PausedBanner /><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric label="Total orders" value={String(visible.length)} note="All-time activity" icon={ClipboardList} /><Metric label="Awaiting settlement" value={String(visible.filter(o => o.status === 'PENDING').length)} note="Requires attention" icon={FileClock} /><Metric label="Settled orders" value={String(visible.filter(o => o.status === 'SETTLED').length)} note="Completed on chain" icon={BadgeCheck} /></div><Panel><div className="flex flex-wrap items-center justify-between gap-3 p-5"><div className="flex flex-wrap gap-1">{['ALL','PENDING','SETTLED','CANCELLED'].map(f => <Button key={f} size="sm" variant={filter === f ? 'secondary' : 'ghost'} onClick={() => setFilter(f)} className="text-xs">{f === 'ALL' ? 'All orders' : f[0] + f.slice(1).toLowerCase()}</Button>)}</div>{can(user, 'investor') && <Button size="sm" onClick={() => { setInvestor(user.address); setOpen(true); setReceipt(null); }}><Plus /> New order</Button>}</div><DataTable rows={filtered} columns={[{ title: 'Order ID', render: o => <span className="font-mono text-xs font-bold text-primary">{o.id}</span> }, { title: 'Investor', render: o => <div className="font-semibold">{investorName(o.investor)}<div><AddressChip value={o.investor} /></div></div> }, { title: 'Type', render: o => <span className="flex items-center gap-1 text-xs font-semibold">{o.type === 'SUBSCRIBE' ? <ArrowDownLeft className="size-4 text-positive" /> : <ArrowUpRight className="size-4 text-warning" />}{o.type}</span> }, { title: 'Units / Value', render: o => <div className="font-semibold">{num(o.units)}<div className="text-xs font-normal text-muted-foreground">{formatMoney(o.amount)}</div></div> }, { title: 'Status', render: o => <StatusBadge value={o.status} /> }, { title: 'Transaction', render: o => <TxHashChip value={o.txHash} block={o.blockNumber} /> }, { title: 'Action', render: o => o.status === 'PENDING' ? <div className="flex gap-1">{can(user, 'agent') && <Button size="sm" variant="outline" onClick={() => setConfirm({ id: o.id, action: 'settle' })}>Settle</Button>}{(can(user, 'investor') && o.investor === user.address) && <Button size="sm" variant="ghost" onClick={() => setConfirm({ id: o.id, action: 'cancel' })}>Cancel</Button>}</div> : <span className="text-muted-foreground">—</span> }]} /></Panel>{receipt && <div className="mt-4 max-w-md"><Receipt receipt={receipt} /></div>}<Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Place an order</DialogTitle><DialogDescription>Submit a subscription or redemption for settlement.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={async e => { e.preventDefault(); const result = await act(() => api.submitOrder(type, { investor, units: Number(units) }), 'Order submitted'); if (result) { setReceipt({ txHash: result.txHash || '', blockNumber: result.blockNumber || 0, message: 'Order submitted' }); setOpen(false); setUnits(''); } }}><Field label="Order type"><SelectField value={type} onChange={v => setType(v as 'subscribe'|'redeem')}><option value="subscribe">Subscribe</option><option value="redeem">Redeem</option></SelectField></Field><Field label="Investor"><SelectField value={investor} onChange={setInvestor}>{investors.filter(i => !investorRole(user.username) || i.address === user.address).map(i => <option key={i.address} value={i.address}>{i.name}</option>)}</SelectField></Field><Field label="Units"><Input type="number" min="1" step="1" required value={units} onChange={e => setUnits(e.target.value)} placeholder="e.g. 1,000" /></Field><div className="rounded bg-muted p-3 text-xs text-muted-foreground">Estimated value: <b className="text-foreground">{formatMoney(Number(units || 0) * 105 * PRICE_SCALE)}</b></div><DialogFooter><Button type="submit">Submit order</Button></DialogFooter></form></DialogContent></Dialog><ConfirmDialog open={!!confirm} setOpen={() => setConfirm(null)} title={`${confirm?.action === 'settle' ? 'Settle' : 'Cancel'} order?`} description={`This action will be recorded against ${confirm?.id || 'the order'} and cannot be undone.`} confirm={confirm?.action === 'settle' ? 'Settle order' : 'Cancel order'} destructive={confirm?.action === 'cancel'} onConfirm={() => void perform()} /></>; }
function Nav({ user }: { user: DemoUser }) { const { data: history = [] } = useData('nav-history', api.getNavHistory); const act = useAct(); const [value, setValue] = useState(''); const [receipt, setReceipt] = useState<TxResult | null>(null); const current = history.at(-1); const scaled = Number(value) * PRICE_SCALE; const change = current && scaled ? (scaled / current.nav - 1) * 100 : 0; const invalid = Math.abs(change) > 20; return <><div className="mb-6 grid gap-4 sm:grid-cols-3"><Metric label="Current NAV" value={current ? formatMoney(current.nav) : '—'} note={current ? `Published ${date(current.date)}` : '—'} icon={Landmark} /><Metric label="Unit price" value={current ? formatMoney(current.unitPrice) : '—'} note="Current valuation per unit" icon={Activity} /><Metric label="NAV entries" value={String(history.length)} note="Recorded valuations" icon={FileClock} /></div><div className="grid gap-6 xl:grid-cols-[minmax(0,1.4fr)_minmax(310px,1fr)]"><Panel><div className="p-5"><SectionHead title="Valuation history" /></div><DataTable rows={[...history].reverse()} pageSize={8} columns={[{ title: 'Valuation date', render: p => <span className="font-semibold">{date(p.date)}</span> }, { title: 'Net asset value', render: p => <span className="font-semibold">{formatMoney(p.nav)}</span> }, { title: 'Unit price', render: p => formatMoney(p.unitPrice) }]} /></Panel><div className="space-y-5">{can(user, 'agent') && <Panel className="p-5 sm:p-6"><SectionHead title="Publish new NAV" /><p className="mb-5 text-xs leading-5 text-muted-foreground">Submit a new fund valuation. Changes exceeding ±20% are rejected.</p><form className="space-y-5" onSubmit={async e => { e.preventDefault(); const r = await act(() => api.updateNav(scaled), 'NAV published'); if (r) { setReceipt(r); setValue(''); } }}><Field label="New net asset value (USD)"><Input type="number" required min="1" step="0.01" placeholder="e.g. 10,900,000.00" value={value} onChange={e => setValue(e.target.value)} /></Field><div className="space-y-3 rounded bg-muted p-4 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">Current NAV</span><b>{current ? formatMoney(current.nav) : '—'}</b></div><div className="flex justify-between"><span className="text-muted-foreground">Change</span><b className={invalid ? 'text-destructive' : 'text-positive'}>{value ? `${change >= 0 ? '+' : ''}${change.toFixed(2)}%` : '—'}</b></div><div className="flex justify-between border-t border-border pt-3"><span className="text-muted-foreground">Est. unit price</span><b>{value && current ? formatMoney(current.unitPrice * (1 + change / 100)) : '—'}</b></div></div>{invalid && <div className="rounded border border-destructive/20 bg-danger-soft p-3 text-xs font-semibold text-destructive">Change exceeds the ±20% limit. This update will be rejected.</div>}<Button type="submit" disabled={!value || invalid} className="w-full">Publish NAV <ArrowRight /></Button></form><div className="mt-4"><Receipt receipt={receipt} /></div></Panel>}</div></div></>; }
function Transfers({ user }: { user: DemoUser }) { const { data: investors = [] } = useData('investors', api.getInvestors); const act = useAct(); const [to, setTo] = useState(''); const [units, setUnits] = useState(''); const [receipt, setReceipt] = useState<TxResult | null>(null); const me = investors.find(i => i.address === user.address); return <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(310px,1fr)]"><Panel className="p-6"><SectionHead title="Transfer fund units" />{can(user, 'investor') ? <form className="max-w-xl space-y-5" onSubmit={async e => { e.preventDefault(); const r = await act(() => api.transfer({ from: user.address, to, units: Number(units) }), 'Transfer completed'); if (r) { setReceipt(r); setUnits(''); } }}><Field label="From investor"><Input value={me?.name || user.name} disabled /></Field><Field label="Recipient"><SelectField value={to} onChange={setTo}><option value="">Select recipient</option>{investors.filter(i => i.address !== user.address && i.kyc === 'APPROVED').map(i => <option key={i.address} value={i.address}>{i.name} · {shortAddress(i.address)}</option>)}</SelectField></Field><Field label="Number of units"><Input type="number" min="1" max={me?.units || 0} step="1" required value={units} onChange={e => setUnits(e.target.value)} /></Field><Button disabled={!to || !units} type="submit">Transfer units <ArrowRight /></Button><Receipt receipt={receipt} /></form> : <Empty text="Transfers can be initiated from an investor account." />}</Panel><Panel className="h-fit p-6"><SectionHead title="Your holdings" /><div className="font-display text-3xl font-bold">{num(me?.units || 0)} <span className="text-sm font-medium text-muted-foreground">units</span></div><p className="mt-3 text-xs text-muted-foreground">Transfers are recorded on chain and require approved recipient accounts.</p></Panel></div>; }
function Custody({ user }: { user: DemoUser }) {
  const { data: positions = [] } = useData('custody-positions', api.getCustodyPositions);
  const { data: actions = [] } = useData('custody-actions', api.getCustodyActions);
  const act = useAct();
  const [type, setType] = useState<CustodyAction['type']>('LOCK');
  const [investor, setInvestor] = useState('');
  const [units, setUnits] = useState('');
  const [assetRef, setAssetRef] = useState('ISIN:US0000001');
  const [reason, setReason] = useState('Collateral pledge');
  const [receipt, setReceipt] = useState<TxResult | null>(null);
  const totals = positions.reduce((acc, p) => ({ balance: acc.balance + p.balance, locked: acc.locked + p.locked, free: acc.free + p.free }), { balance: 0, locked: 0, free: 0 });
  return <><div className="mb-6 grid gap-4 sm:grid-cols-3"><Metric label="Units under custody" value={num(totals.balance)} note={`${positions.length} investor positions`} icon={Wallet} /><Metric label="Locked units" value={num(totals.locked)} note="Pledged as collateral" icon={LockKeyhole} /><Metric label="Free units" value={num(totals.free)} note="Available to trade" icon={BadgeCheck} positive /></div><div className="grid gap-6 xl:grid-cols-[minmax(0,1.5fr)_minmax(300px,1fr)]"><div className="space-y-6"><Panel><div className="p-5"><SectionHead title="Positions by investor" /></div><DataTable rows={positions} pageSize={5} columns={[{ title: 'Investor', render: p => <div><div className="font-semibold">{p.name}</div><AddressChip value={p.investor} /></div> }, { title: 'Units held', render: p => <span className="font-semibold">{num(p.balance)}</span> }, { title: 'Locked', render: p => <span className="font-semibold text-warning">{num(p.locked)}</span> }, { title: 'Free', render: p => <span className="font-semibold text-positive">{num(p.free)}</span> }]} /></Panel><Panel><div className="p-5"><SectionHead title="Custody actions" /></div><DataTable rows={actions} columns={[{ title: 'Reference', render: a => <span className="font-mono text-xs font-bold">{a.id}</span> }, { title: 'Action', render: a => <StatusBadge value={a.type} /> }, { title: 'Investor', render: a => <AddressChip value={a.investor} /> }, { title: 'Units / Value', render: a => <div className="font-semibold">{num(a.units)}<div className="text-xs font-normal text-muted-foreground">{formatMoney(a.amount)}</div></div> }, { title: 'Asset', render: a => <span className="text-xs">{a.asset}</span> }, { title: 'Transaction', render: a => <TxHashChip value={a.txHash} block={a.blockNumber} /> }]} /></Panel></div>{can(user, 'custodian') && <Panel className="h-fit p-5"><SectionHead title="New custody action" /><p className="mb-4 text-xs leading-5 text-muted-foreground">Custody is recorded on chain against an investor, in fund units. Locked units cannot be redeemed or transferred.</p><form className="space-y-4" onSubmit={async e => { e.preventDefault(); const r = await act(() => api.createCustodyAction({ type, investor, units: Number(units), assetRef, reason }), 'Custody action recorded'); if (r) { setReceipt(r); setUnits(''); } }}><Field label="Action"><SelectField value={type} onChange={v => setType(v as CustodyAction['type'])}><option>LOCK</option><option>RELEASE</option><option>TRANSFER</option></SelectField></Field><Field label="Investor"><SelectField value={investor} onChange={setInvestor}><option value="">Select investor</option>{positions.map(p => <option key={p.investor} value={p.investor}>{p.name} · {num(p.free)} free</option>)}</SelectField></Field><Field label="Units"><Input required min="1" step="1" type="number" value={units} onChange={e => setUnits(e.target.value)} placeholder="e.g. 50" /></Field><Field label="Asset reference"><Input required value={assetRef} onChange={e => setAssetRef(e.target.value)} /></Field><Field label="Reason"><Input required value={reason} onChange={e => setReason(e.target.value)} /></Field><Button className="w-full" type="submit" disabled={!investor || !units}>Submit action</Button><Receipt receipt={receipt} /></form></Panel>}</div></>;
}
function Admin({ user }: { user: DemoUser }) { const { data: status } = useData('fund-status', api.getFundStatus); const { data: roles = [] } = useData('admin-roles', api.getAdminRoles); const act = useAct(); const [confirm, setConfirm] = useState(false); const [receipt, setReceipt] = useState<TxResult | null>(null); return <div className="grid gap-6 xl:grid-cols-[minmax(0,1.4fr)_minmax(300px,1fr)]"><Panel><div className="p-5"><SectionHead title="Role assignments" /></div><DataTable rows={roles} columns={[{ title: 'Account', render: r => <span className="font-semibold">{r.name}</span> }, { title: 'Role', render: r => <span className="rounded bg-secondary px-2 py-1 text-xs font-semibold capitalize text-secondary-foreground">{r.username}</span> }, { title: 'Address', render: r => <AddressChip value={r.address} /> }]} /></Panel><Panel className="h-fit p-6"><SectionHead title="Fund controls" /><div className="mb-5 flex items-center justify-between"><span className="text-sm text-muted-foreground">Operational status</span><StatusBadge value={status?.paused ? 'PAUSED' : 'ACTIVE'} /></div><p className="mb-5 text-xs leading-5 text-muted-foreground">Pausing the fund prevents new order submissions until operations resume.</p>{can(user, 'admin') && <Button className="w-full" variant={status?.paused ? 'default' : 'destructive'} onClick={() => setConfirm(true)}>{status?.paused ? 'Resume fund' : 'Pause fund'}</Button>}<div className="mt-4"><Receipt receipt={receipt} /></div></Panel><ConfirmDialog open={confirm} setOpen={setConfirm} title={status?.paused ? 'Resume fund operations?' : 'Pause fund operations?'} description={status?.paused ? 'Investors will be able to submit orders again.' : 'Investors will not be able to submit new orders until the fund is resumed.'} confirm={status?.paused ? 'Resume fund' : 'Pause fund'} destructive={!status?.paused} onConfirm={() => { void (async () => { const r = await act(() => api.setFundPause(!status?.paused), status?.paused ? 'Fund resumed' : 'Fund paused'); if (r) setReceipt(r); })(); }} /></div>; }
function Reports({ user }: { user: DemoUser }) { const { data: investors = [] } = useData('investors', api.getInvestors); const { data: transactions = [] } = useData('transactions', api.getTransactions); const [address, setAddress] = useState(user.address); const [style, setStyle] = useState('traditional'); const [format, setFormat] = useState('json'); const [preview, setPreview] = useState<unknown>(null); const act = useAct(); const exportStatement = async () => { const data = await act(() => api.getInvestorStatement(address, style, format), 'Statement generated'); if (!data) return; setPreview(data); if (format === 'json') { const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = `statement-${address.slice(0,8)}.json`; a.click(); URL.revokeObjectURL(url); } }; return <><div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(300px,1fr)]"><Panel className="p-6"><SectionHead title="Investor statement" /><div className="max-w-xl space-y-5"><Field label="Investor"><SelectField value={address} onChange={setAddress}>{investors.filter(i => !investorRole(user.username) || i.address === user.address).map(i => <option key={i.address} value={i.address}>{i.name}</option>)}</SelectField></Field><Field label="Statement style"><div className="flex rounded border border-border p-1">{['traditional','blockchain-native'].map(s => <Button key={s} className="flex-1 capitalize" variant={style === s ? 'secondary' : 'ghost'} size="sm" onClick={() => setStyle(s)}>{s.replace('-', ' ')}</Button>)}</div></Field><Field label="Format"><div className="flex gap-2">{['json','csv','pdf'].map(f => <Button key={f} variant={format === f ? 'secondary' : 'outline'} size="sm" onClick={() => setFormat(f)}>{f.toUpperCase()}</Button>)}</div></Field><Button onClick={() => void exportStatement()} disabled={!address}><Download /> Generate statement</Button></div></Panel><Panel className="h-fit p-6"><SectionHead title="Statement preview" />{preview ? <pre className="max-h-80 overflow-auto rounded bg-muted p-3 text-[10px] leading-5 text-foreground">{JSON.stringify(preview, null, 2)}</pre> : <div className="py-12 text-center text-xs text-muted-foreground">Generate a statement to see its contents.</div>}</Panel></div><Panel className="mt-6"><div className="p-5"><SectionHead title="Transaction report" /></div><DataTable rows={transactions} columns={[{ title: 'Order', render: o => <span className="font-mono text-xs font-bold">{o.id}</span> }, { title: 'Type', render: o => o.type }, { title: 'Investor', render: o => <AddressChip value={o.investor} /> }, { title: 'Amount', render: o => <b>{formatMoney(o.amount)}</b> }, { title: 'Date', render: o => date(o.date) }, { title: 'Transaction', render: o => <TxHashChip value={o.txHash} block={o.blockNumber} /> }]} /></Panel></>; }
function Audit() { const { data: events = [] } = useData('events', api.getAuditEvents); const [results, setResults] = useState<Record<string, boolean>>({}); const [loading, setLoading] = useState<string | null>(null); const verify = async (hash: string) => { setLoading(hash); try { const r = await api.verifyOnChain(hash); setResults(v => ({ ...v, [hash]: r.match })); toast[r.match ? 'success' : 'error'](r.match ? 'On-chain record matches' : 'On-chain record does not match'); } catch (e) { toast.error(errorMessage(e)); } finally { setLoading(null); } }; return <Panel><div className="p-5"><SectionHead title="Immutable event log" aside={<span className="text-xs text-muted-foreground">{events.length} events</span>} /></div><DataTable rows={events} columns={[{ title: 'Event', render: e => <div><span className="font-semibold">{e.action}</span><div className="mt-1 font-mono text-[11px] text-muted-foreground">{e.id}</div></div> }, { title: 'Actor', render: e => e.actor }, { title: 'Timestamp', render: e => <span className="text-xs">{datetime(e.date)}</span> }, { title: 'Transaction hash', render: e => <TxHashChip value={e.txHash} block={e.blockNumber} /> }, { title: 'Verification', render: e => results[e.txHash] !== undefined ? <StatusBadge value={results[e.txHash] ? 'MATCH' : 'MISMATCH'} /> : <Button variant="outline" size="sm" disabled={loading === e.txHash} onClick={() => void verify(e.txHash)}><ShieldCheck className="size-3" />{loading === e.txHash ? 'Verifying…' : 'Verify on chain'}</Button> }]} /></Panel>; }
function Live() { const { data: events = [] } = useData('events', api.getAuditEvents); const qc = useQueryClient(); const [connected, setConnected] = useState(false); const [incoming, setIncoming] = useState<AuditEvent[]>([]); useEffect(() => { let ws: WebSocket | undefined; let timer: ReturnType<typeof setTimeout>; let disposed = false; const connect = () => { ws = new WebSocket(WS_URL); ws.onopen = () => setConnected(true); ws.onmessage = event => { try { const mapped = mapWsEvent(JSON.parse(event.data as string)); if (mapped) { setIncoming(v => [mapped, ...v]); void qc.invalidateQueries(); } } catch { /* ignore unrecognised events */ } }; ws.onclose = () => { setConnected(false); if (!disposed) timer = setTimeout(connect, 3000); }; ws.onerror = () => ws?.close(); }; connect(); return () => { disposed = true; clearTimeout(timer); ws?.close(); }; }, [qc]); const feed = [...incoming, ...events].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()); return <div className="grid gap-6 xl:grid-cols-[minmax(0,1.5fr)_minmax(300px,1fr)]"><Panel className="p-5 sm:p-6"><SectionHead title="Event timeline" aside={<span className={`flex items-center gap-2 text-xs font-semibold ${connected ? 'text-positive' : 'text-warning'}`}><span className={`live-dot size-2 rounded-full ${connected ? 'bg-positive' : 'bg-warning'}`} />{connected ? 'Connected' : 'Reconnecting'}</span>} /><div className="space-y-0">{feed.map((e, i) => <div key={`${e.id}-${i}`} className="flex gap-4 border-b border-border py-4 last:border-0"><div className="flex size-9 shrink-0 items-center justify-center rounded bg-secondary text-primary"><Activity className="size-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><span className="text-sm font-semibold">{e.action}</span><span className="text-xs text-muted-foreground">{datetime(e.date)}</span></div><div className="mt-1 text-xs text-muted-foreground">{e.actor}</div><div className="mt-2"><TxHashChip value={e.txHash} block={e.blockNumber} /></div></div></div>)}{!feed.length && <Empty text="Waiting for fund events…" />}</div></Panel><Panel className="h-fit p-6"><SectionHead title="Connection status" /><div className="flex items-center gap-3"><StatusBadge value={connected ? 'ACTIVE' : 'PENDING'} /><span className="text-xs text-muted-foreground">Live WebSocket stream</span></div><p className="mt-4 text-xs leading-5 text-muted-foreground">Events update automatically as fund operations are recorded.</p></Panel></div>; }
